import{z as n,x as A,o as t,c as d,q as r,j as l,D as e,d as o,s as B,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"MEMS 图形化","description":"","frontmatter":{"title":"MEMS 图形化","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mems-patterning.md","filePath":"litho/mems-patterning.md","lastUpdated":1791413859000}'),p={name:"litho/mems-patterning.md"};function M(m,a,h,S,D,C){const s=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=r('<h1 id="mems-图形化" tabindex="-1">MEMS 图形化 <a class="header-anchor" href="#mems-图形化" aria-label="Permalink to &quot;MEMS 图形化&quot;">​</a></h1><div class="epigraph"><p>MEMS 要的是深槽、厚胶和释放后的三维；分辨率往往不是墙，深宽比、残余应力和双面套刻才是。</p><footer>—— 对照 MEMS 光刻与 Bosch 深硅刻蚀的通称</footer></div><p><a href="/litho/photonics-patterning">上一课</a>把目标函数换成损耗。缺口是力学器件。本课钉 MEMS 图形化。灰度把第三维写进胶厚，留给<a href="/litho/grayscale-litho">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>惯性传感器、喷墨、射频 MEMS：胶厚可达数十微米，曝光用接触/接近式或专用投影，DOF 与侧壁垂直度关键。深硅常用 Bosch 时分钝化（各向异性课对照过）。双面光刻对准、释放孔、残余应力导致的翘曲，比 MMP 更像封装面板问题。LIGA 的 X 射线厚胶是尼奇。</p><p>缺口是<strong>厚胶三维</strong>，不是先进节点 k1。用 EUV 随机语言谈 MEMS 会错对象。</p><p><span class="marginnote">把&quot;释放&quot;想象成拆脚手架：可动结构原本埋在牺牲层里，刻掉牺牲层后才悬空。潮湿时水膜的表面张力会把细梁拉塌、粘死在基底上——所以要用超临界干燥，让液体绕过气液界面直接变气体，结构才不会被&quot;拔河&quot;拔断。</span></p><h3 id="与-cmos-mems-集成" tabindex="-1">与 CMOS-MEMS 集成 <a class="header-anchor" href="#与-cmos-mems-集成" aria-label="Permalink to &quot;与 CMOS-MEMS 集成&quot;">​</a></h3><p>共集成时前道光刻污染 MEMS 释放，或 MEMS 形貌破坏后道光刻焦深。集成顺序是 DTCO。</p><p><span class="marginnote">接触式光刻的颗粒打印在厚胶 MEMS 上仍致命，只是杀手尺寸不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工具：接触对准机、厚胶步进器。工艺：多层套刻、释放、超临界干燥（塌缩课同族）。计量：剖面、应力、动静态电学。灰度下一课可服务斜面与透镜。</p>',12)),(t(),l(i,null,{default:e(()=>[B(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20COAT%5B%22%E6%97%8B%E6%B6%82%E5%8E%9A%E8%83%B6%3A%20%E6%95%B0%E5%8D%81%E5%BE%AE%E7%B1%B3%22%5D%20--%3E%20EXP%5B%22%E6%8E%A5%E8%A7%A6%20%2F%20%E6%8E%A5%E8%BF%91%E5%BC%8F%E6%9B%9D%E5%85%89%22%5D%0A%20%20EXP%20--%3E%20DEV%5B%22%E6%98%BE%E5%BD%B1%3A%20%E5%8E%9A%E8%83%B6%E4%B8%89%E7%BB%B4%E8%BD%AE%E5%BB%93%22%5D%0A%20%20DEV%20--%3E%20BOSCH%7B%22Bosch%20%E5%BE%AA%E7%8E%AF%22%7D%0A%20%20BOSCH%20--%3E%7C%22%E5%88%BB%E8%9A%80%E6%AD%A5%22%7C%20E%5B%22%E5%90%84%E5%90%91%E5%BC%82%E6%80%A7%E6%8C%96%E7%A1%85%22%5D%0A%20%20BOSCH%20--%3E%7C%22%E9%92%9D%E5%8C%96%E6%AD%A5%22%7C%20P%5B%22%E4%BE%A7%E5%A3%81%E6%B2%89%E7%A7%AF%E4%BF%9D%E6%8A%A4%E8%86%9C%22%5D%0A%20%20E%20--%3E%20BOSCH%0A%20%20P%20--%3E%20BOSCH%0A%20%20BOSCH%20--%3E%20REL%5B%22%E9%87%8A%E6%94%BE%20%2F%20%E5%B9%B2%E7%87%A5%20%2F%20%E5%BA%94%E5%8A%9B%E8%AF%84%E4%BC%B0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},'"时分钝化"（Bosch 工艺）就是"切一刀、糊一层"的循环：先各向异性刻一刀，再在侧壁沉积一层保护膜，下一刀只切得动底部。循环往复挖出又深又直的槽，代价是侧壁留下扇贝状的波纹——它会进力学疲劳，所以不是纯美观问题。')],-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},'初学者容易用"分辨率多小"评估 MEMS 光刻。实际厚胶几十微米时，难的是侧壁垂直、深槽不塌、双面套刻对得上——分辨率往往余量很大，残余应力与深宽比才是墙，这也是它和先进节点光刻"考点"不同的地方。')],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[o("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"厚胶吸收与显影前沿给出倾斜侧壁，除非工艺针对垂直。Bosch 扇形波纹进力学疲劳。应力与光刻图形密度通过结构刚度耦合——布局即力学。",-1)),(t(),l(i,null,{default:e(()=>[B(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20THK%5B%22%E5%8E%9A%E8%83%B6%22%5D%20--%3E%20MEMS%5B%22%E6%B7%B1%E6%A7%BD%20%2F%20%E7%BB%93%E6%9E%84%22%5D%0A%20%20BOSCH%5B%22%E6%97%B6%E5%88%86%E9%92%9D%E5%8C%96%E5%88%BB%E8%9A%80%22%5D%20--%3E%20MEMS%0A%20%20STRESS%5B%22%E6%AE%8B%E4%BD%99%E5%BA%94%E5%8A%9B%22%5D%20--%3E%20MECH%5B%22%E7%BF%98%E6%9B%B2%20%2F%20%E9%A2%91%E5%81%8F%22%5D%0A%20%20MEMS%20--%3E%20MECH%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把所有 MEMS 当 Bosch。不进入某传感器设计。X 射线 LIGA 仅尼奇。</p><p>后课默认：MEMS 常要三维胶轮廓；下一课灰度曝光故意把剂量写成高度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MEMS 光刻墙在厚胶、深宽比、应力与双面套刻。</li><li>Bosch 与释放工艺定义侧壁，分辨率其次。</li><li>与 CMOS 共集成是顺序 DTCO。</li><li>出处：MEMS 光刻与深硅刻蚀通称。</li></ul>',5))])}const f=n(p,[["render",M]]);export{c as __pageData,f as default};
